-- Read consumers: traverse + broad domain read via inheritance
GRANT USE CATALOG ON CATALOG sales TO `analysts`;
GRANT USE SCHEMA, SELECT ON SCHEMA sales.gold TO `analysts`;

-- Producers: create and write within a layer
GRANT USE CATALOG ON CATALOG sales TO `data_eng`;
GRANT USE SCHEMA, CREATE TABLE, MODIFY ON SCHEMA sales.silver TO `data_eng`;

-- Exception: restrict a single sensitive table to a smaller group
GRANT SELECT ON TABLE sales.gold.customer_pii TO `pii_readers`;
REVOKE SELECT ON TABLE sales.gold.customer_pii FROM `analysts`;

SHOW GRANTS ON SCHEMA sales.gold;

-- Classify a sensitive column with a tag
ALTER TABLE sales.gold.customers
  ALTER COLUMN email SET TAGS ('classification' = 'pii');

-- A masking function: show full email only to pii_readers
CREATE FUNCTION sales.gold.mask_email(e STRING)
  RETURN CASE WHEN is_account_group_member('pii_readers') THEN e
              ELSE regexp_replace(e, '(^.).*(@.*$)', '$1***$2') END;

ALTER TABLE sales.gold.customers
  ALTER COLUMN email SET MASK sales.gold.mask_email;

-- A row filter restricting rows to the caller's region
CREATE FUNCTION sales.gold.region_filter(region STRING)
  RETURN is_account_group_member('global_readers') OR region = current_user_region();

ALTER TABLE sales.gold.customers
  SET ROW FILTER sales.gold.region_filter ON (region);
